Translate("frFR", "darnassus", {
	title = "Darnassus",
	sections = {
		{
			title = "Résumé",
			text = [=[Darnassus est la capitale des {link:night-elves}elfes de la nuit{/link}, une cité de bois vivant et d'eaux baignées de lune, dans les hautes branches de {link:teldrassil}Teldrassil{/link}. Ses salles ont poussé plutôt qu'elles n'ont été bâties. Ses terrasses s'ouvrent sur des jardins et des bassins paisibles, et le {link:temple-of-the-moon}Temple de la Lune{/link} brille en son cœur. C'est une cité jeune d'un peuple ancien. Les kaldorei l'élevèrent après la {link:third-war}Troisième Guerre{/link}, quand ils eurent perdu leur immortalité et que leur ancien foyer du {link:mount-hyjal}mont Hyjal{/link} gisait meurtri, et ils voulurent en faire un nouveau commencement.]=],
		},
		{
			title = "Origines",
			text = [=[Quand la guerre contre la {link:burning-legion}Légion ardente{/link} fut finie, l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link} et ses druides firent croître {link:teldrassil}Teldrassil{/link} au-delà de la côte nord. Darnassus s'éleva dans sa couronne. Les prêtresses d'Élune y installèrent leur temple, les druides leur enclave, et les {link:sentinels}Sentinelles{/link} leur caserne. Depuis {link:rut-theran-village}Rut'theran{/link}, loin en contrebas, un portail emporte les voyageurs jusqu'à la cité.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Deux chefs siègent à Darnassus. La grande prêtresse {link:tyrande-whisperwind}Tyrande Whisperwind{/link} gouverne la cité et son peuple selon la volonté d'Élune. {link:fandral-staghelm}Fandral Staghelm{/link} dirige les druides pendant la longue absence de {link:malfurion-stormrage}Malfurion Stormrage{/link}, qui n'est pas revenu du {link:emerald-dream}Rêve d'émeraude{/link}. Tyrande demande à son peuple de respecter son rang, mais elle lui rappelle que les affaires de Darnassus ne regardent qu'elle. Fandral, pour sa part, ne se fie à personne hors de son enclave. Lui et le gardien {link:keeper-remulos}Remulos{/link} de {link:moonglade}Reflet-de-Lune{/link} se soupçonnent mutuellement de fourberie, et les maux de l'Arbre-Monde ne guérissent pas. Les {link:sentinels}Sentinelles{/link} montent une garde attentive jusque dans la cité, car quelque chose ne va pas sur {link:teldrassil}Teldrassil{/link}.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les prêtresses d'Élune.{/b} Elles veillent sur le {link:temple-of-the-moon}Temple de la Lune{/link} et soignent les {link:night-elves}kaldorei{/link}.
• {b}Les druides du {link:cenarion-circle}Cercle cénarien{/link}.{/b} Ils étudient dans l'{link:cenarion-enclave}Enclave cénarienne{/link} sous l'autorité de l'archidruide.
• {b}Les {link:sentinels}Sentinelles{/link}.{/b} Les guerrières qui gardent la cité et les forêts au-delà.
• {b}Les alliés de l'{link:alliance}Alliance{/link}.{/b} Des érudits nains de la {link:explorers-league}Ligue des explorateurs{/link} et des émissaires de l'{link:argent-dawn}Aube d'argent{/link} sont venus dans la cité.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La fondation.{/b} La cité fut élevée dans les branches du nouvel Arbre-Monde après la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}.
• {b}Les puits de lune.{/b} Les druides de la cité puisent aux puits de lune de {link:teldrassil}Teldrassil{/link}, et des messagers montent des fioles de leur eau depuis {link:shadowglen}Sombrevallon{/link}, {link:dolanaar}Dolanaar{/link} et la {link:the-oracle-glade}Clairière de l'Oracle{/link}.
• {b}La rupture avec {link:moonglade}Reflet-de-Lune{/link}.{/b} L'archidruide et le gardien {link:keeper-remulos}Remulos{/link} se sont éloignés l'un de l'autre, et les druides de la cité servent le Cercle sous un nuage de soupçons.
• {b}Aujourd'hui.{/b} Les {link:night-elves}kaldorei{/link} ont rejoint l'{link:alliance}Alliance{/link}, et des héros de tous les peuples arpentent désormais les terrasses de Darnassus.]=],
		},
		{
			title = "Savoir de la cité",
			text = [=[• Une fontaine au cœur du {link:temple-of-the-moon}Temple de la Lune{/link} contient une eau bénite qui, dit-on, purifie ce qu'elle touche.
• L'arbre de l'archidruide se dresse dans l'{link:cenarion-enclave}Enclave cénarienne{/link}, et des tunnels courent sous lui.
• Les druides de Darnassus étudient une terre rapportée du lointain {link:un-goro-crater}cratère d'Un'Goro{/link}, et ils y font pousser des herbes dont ils ne comprennent pas encore la nature.]=],
		},
	},
})

Translate("frFR", "temple-of-the-moon", {
	title = "Temple de la Lune",
	aliases = { "Jardins du temple", "Les Jardins du temple" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Temple de la Lune se dresse parmi les Jardins du temple, au sud de {link:darnassus}Darnassus{/link}. C'est la maison d'Élune et le siège de la grande prêtresse. {link:tyrande-whisperwind}Tyrande Whisperwind{/link} tient sa cour dans sa salle supérieure. En dessous, les prêtresses instruisent les jeunes et soignent les blessés, et une fontaine d'eau bénite jaillit en son centre. Les offrandes déposées dans cette fontaine sont données à la déesse. Des {link:sentinels}Sentinelles{/link} gardent ses portes et y prient chaque jour, car une chasseresse d'Élune doit manier les dons de sa déesse aussi bien que sa lame.]=],
		},
	},
})

Translate("frFR", "cenarion-enclave", {
	title = "Enclave cénarienne",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Enclave cénarienne est le quartier des druides, au nord de {link:darnassus}Darnassus{/link}. Ici pousse le grand arbre de l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link}, où il étudie les maux de {link:teldrassil}Teldrassil{/link} avec son second, {link:mathrengyl-bearwalker}Mathrengyl Bearwalker{/link}, à l'étage inférieur. Des druides comme {link:rellian-greenspyre}Rellian Greenspyre{/link} parcourent ses sentiers. Les chasseurs et les voleurs y ont aussi leurs salles. Derrière l'arbre de l'archidruide, des tas d'une terre étrange venue de contrées lointaines attendent d'être triés, et des tunnels descendent dans les profondeurs sous l'Enclave.]=],
		},
	},
})

Translate("frFR", "warriors-terrace", {
	title = "Terrasse des Guerriers",
	sections = {
		{
			title = "Résumé",
			text = [=[La Terrasse des Guerriers se trouve à l'est de {link:darnassus}Darnassus{/link}. Ici, les guerriers des {link:night-elves}kaldorei{/link} s'entraînent auprès de maîtres tels qu'Elanaria et Arias'ta Bladesinger, et ici la commandante {link:thyn-tel-bladeweaver}Thyn'tel Bladeweaver{/link} gère les affaires des {link:sentinels}Sentinelles{/link}. Les biens des Sentinelles disparues sont gardés dans leur baraquement jusqu'à leur retour. Une guerrière qui veut en apprendre davantage doit d'abord prouver sa résolution contre les ennemis de l'arbre.]=],
		},
	},
})

Translate("frFR", "craftsmens-terrace", {
	title = "Terrasse des Artisans",
	sections = {
		{
			title = "Résumé",
			text = [=[La Terrasse des Artisans se trouve au nord-est de {link:darnassus}Darnassus{/link}. Les travailleurs du cuir, les tailleurs et d'autres artisans des {link:night-elves}kaldorei{/link} y ont leurs ateliers, et l'auberge de la cité offre le repos aux voyageurs de toutes les contrées. Des émissaires de l'{link:argent-dawn}Aube d'argent{/link} se sont installés parmi les artisans. Le tissu de l'{link:alliance}Alliance{/link} y est aussi rassemblé, pour les besoins de la guerre à venir.]=],
		},
	},
})

Translate("frFR", "tradesmens-terrace", {
	title = "Terrasse des Marchands",
	sections = {
		{
			title = "Résumé",
			text = [=[La Terrasse des Marchands se trouve à l'est de {link:darnassus}Darnassus{/link}, entre les jardins et la {link:warriors-terrace}Terrasse des Guerriers{/link}. C'est le marché de la cité. Des marchands de vivres, de tissu, d'armes et de marchandises diverses tiennent leurs étals le long de ses sentiers sinueux, et les nouvelles de la forêt d'en bas circulent vite parmi eux. C'est le lieu le plus animé de Darnassus, et pourtant plus calme que n'importe quel marché des terres humaines.]=],
		},
	},
})

Translate("frFR", "tyrande-whisperwind", {
	title = "Tyrande Whisperwind",
	subtitle = "Grande prêtresse d'Élune",
	found = "La salle supérieure du Temple de la Lune",
	hint = [=[Montez à la salle supérieure du Temple de la Lune et cherchez la grande prêtresse.]=],
	allegiance = "Elfes de la nuit · Sororité d'Élune · Sentinelles",
	aliases = { "Tyrande", "Grande prêtresse Tyrande Whisperwind" },
	sections = {
		{
			title = "Résumé",
			text = [=[Tyrande Whisperwind est la grande prêtresse d'Élune et la dirigeante des elfes de la nuit. Depuis dix mille ans, elle protège son peuple, d'abord dans les ruines de son antique empire et maintenant dans les branches de {link:teldrassil}Teldrassil{/link}. Elle est la bien-aimée de {link:malfurion-stormrage}Malfurion Stormrage{/link}, et elle attend son retour. Elle gouverne {link:darnassus}Darnassus{/link} avec fermeté, et on la sait bienveillante.]=],
		},
		{
			title = "Importance",
			text = [=[Tyrande est le lien vivant entre les {link:night-elves}kaldorei{/link} d'autrefois et les kaldorei d'aujourd'hui. Elle combattit pendant la {link:war-of-the-ancients}guerre des Anciens{/link} et pendant la {link:third-war}Troisième Guerre{/link}. Sous sa conduite, les {link:sentinels}Sentinelles{/link} devinrent le bouclier de leur peuple, et sous sa conduite, les elfes de la nuit ont rejoint l'{link:alliance}Alliance{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[Tyrande était novice de la Sororité d'Élune au temps de la {link:queen-azshara}reine Azshara{/link}. Les frères jumeaux {link:malfurion-stormrage}Malfurion{/link} et {link:illidan-stormrage}Illidan Stormrage{/link} l'aimaient tous deux, et elle choisit Malfurion. Quand la {link:burning-legion}Légion ardente{/link} vint, elle combattit à leurs côtés, et elle s'éleva jusqu'à la tête de la Sororité durant cette guerre. Après la {link:great-sundering}Fracture{/link}, tandis que les druides dormaient dans le {link:emerald-dream}Rêve d'émeraude{/link}, elle et ses prêtresses veillèrent sur les forêts pendant de longs siècles.

Quand la Légion revint et que les humains et les orcs arrivèrent en {link:kalimdor}Kalimdor{/link}, Tyrande réveilla les druides endormis dans leurs refuges des saisons. Elle libéra Illidan de sa prison, contre la volonté de son bien-aimé. Lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, ses {link:sentinels}Sentinelles{/link} combattirent aux côtés des humains et des orcs jusqu'à la chute d'{link:archimonde}Archimonde{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} est reparti dans le Rêve, et nul ne sait ce qu'il est devenu. Tyrande dirige seule les {link:night-elves}kaldorei{/link}. Elle respecte {link:fandral-staghelm}Fandral Staghelm{/link} en tant qu'archidruide, mais elle ne le laisse pas oublier que son domaine à lui est le druidisme, tandis que le sien est son peuple tout entier. Ses prêtresses et ses {link:sentinels}Sentinelles{/link} lui apportent des nouvelles de toutes les forêts de {link:kalimdor}Kalimdor{/link}, et elle les écoute elle-même. Ceux qui viennent à son temple après avoir servi son peuple la trouvent reconnaissante et généreuse, et prompte à leur demander de partager leurs récits avec les jeunes.]=],
		},
	},
	chapters = {
		{
			title = "L'eau des puits de lune",
			hint = [=[Apportez à la grande prêtresse ce qui reste de l'eau des puits de lune.]=],
			text = [=[Les dernières gouttes de l'eau des puits de lune parvinrent à Tyrande dans un récipient de cérémonie, après que l'archidruide l'eut écarté. Elle remercia le porteur, car chaque goutte était bénie par Élune. Elle parla aussi, brièvement et sèchement, de {link:fandral-staghelm}Fandral{/link} : il avait beaucoup accompli en l'absence de {link:malfurion-stormrage}Malfurion{/link}, mais il n'était pas Malfurion.]=],
		},
		{
			title = "Nouvelles des terres sauvages",
			hint = [=[Apportez à la grande prêtresse des nouvelles de ses prêtresses et de ses éclaireuses en terres lointaines.]=],
			text = [=[Les nouvelles parviennent au temple de tous les coins de {link:kalimdor}Kalimdor{/link} : des {link:sentinels}Sentinelles{/link} des {link:stonetalon-mountains}Serres-Rocheuses{/link}, et de la prêtresse {link:jer-kai-moonweaver}Jer'kai{/link}, qui combat {link:grimtotem-clan}les Totem sinistre{/link} à {link:feralas}Féralas{/link}. Tyrande écoute elle-même chaque récit, et elle envoie ses éclaireuses là où on a besoin d'elles.]=],
		},
	},
	mentions = {
		{ text = "L'accueil de Tyrande" },
		{ text = "Rendre la justice" },
		{ text = "À la découverte de l'{link:alliance}Alliance{/link}" },
		{ text = "La couronne de la terre" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "son bien-aimé" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "le frère qu'elle libéra" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "archidruide de son peuple" },
		{ id = "sentinels", name = "Sentinelles", note = "ses gardiennes" },
		{ id = "priestess-a-moora", name = "Prêtresse A'moora", note = "sert dans son temple" },
	},
})

Translate("frFR", "fandral-staghelm", {
	title = "Fandral Staghelm",
	subtitle = "Archidruide de Darnassus",
	found = "Son arbre dans l'Enclave cénarienne",
	hint = [=[Cherchez l'archidruide dans son arbre de l'Enclave cénarienne.]=],
	allegiance = "Elfes de la nuit · Cercle cénarien",
	aliases = { "Fandral", "Archidruide Fandral Staghelm" },
	sections = {
		{
			title = "Résumé",
			text = [=[Fandral Staghelm est l'archidruide des elfes de la nuit. Quand {link:malfurion-stormrage}Malfurion Stormrage{/link} disparut après la {link:third-war}Troisième Guerre{/link}, Fandral prit la tête des druides et résolut que son peuple rebâtirait. Il fit croître {link:teldrassil}Teldrassil{/link}, le nouvel Arbre-Monde, et il travaille encore à le rendre entier. Il est fier, impatient et infatigable, et il ne se fie qu'à lui-même pour achever l'œuvre.]=],
		},
		{
			title = "Importance",
			text = [=[Peu de {link:night-elves}kaldorei{/link} ont façonné l'âge présent plus que Fandral. {link:darnassus}Darnassus{/link} se dresse dans l'arbre qu'il a élevé. Pourtant l'arbre est imparfait, l'immortalité qu'il cherchait n'est pas revenue, et sa querelle avec {link:moonglade}Reflet-de-Lune{/link} divise le {link:cenarion-circle}Cercle cénarien{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[Après la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, {link:nordrassil}Nordrassil{/link} fumait encore et les druides étaient sans chef. Fandral persuada le Cercle des Anciens de {link:darkshore}Sombrivage{/link} que les {link:night-elves}kaldorei{/link} devaient rebâtir et reconquérir leur immortalité. Avec l'accord du Cercle, lui et les plus puissants druides firent croître {link:teldrassil}Teldrassil{/link} au large de la côte nord. Il demanda ensuite aux dragons leur bénédiction. Nozdormu la lui refusa et lui reprocha son arrogance, et {link:alexstrasza}Alexstrasza{/link} la refusa aussi. Privé de leurs dons, l'arbre a poussé imparfait et imprévisible.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Fandral travaille sans relâche aux problèmes de l'arbre, et il les appelle un joug dont il voudrait être libéré. Il croit avoir seul conduit son peuple hors des ténèbres, et il qualifie les paroles de {link:moonglade}Reflet-de-Lune{/link} de propagande. Le gardien {link:keeper-remulos}Remulos{/link} et lui se soupçonnent l'un l'autre. Même son propre second admet que l'air entre eux est lourd de méfiance.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fit croître {link:teldrassil}Teldrassil{/link}, le nouvel Arbre-Monde.
• Il étudie les terres d'{link:un-goro-crater}Un'Goro{/link} et l'herbe grain-du-matin.
• Il envoie des messages à {link:onu}Onu{/link}, l'Ancien du savoir de {link:darkshore}Sombrivage{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur la vie de Fandral avant la {link:third-war}Troisième Guerre{/link}. Cette entrée ne rapporte que ses actes depuis.]=],
		},
	},
	chapters = {
		{
			title = "La couronne de la terre",
			hint = [=[Apportez à l'archidruide l'eau des puits de lune de Teldrassil.]=],
			text = [=[Le récipient rempli aux puits de lune de l'arbre parvint enfin à Fandral. Il grommela que cela avait pris trop de temps et que les messagers n'étaient pas des plus fiables. Puis il parla du poids des problèmes de {link:teldrassil}Teldrassil{/link} sur ses épaules.]=],
		},
		{
			title = "Le rapport de l'Oracle",
			hint = "Remettez à l'archidruide le rapport de l'arbre de l'Oracle.",
			text = [=[L'arbre de l'Oracle était resté longtemps silencieux. Son rapport apprit à Fandral que certains maux de l'arbre s'étaient atténués tandis que d'autres avaient empiré. Il craignit à voix haute que son œuvre ne soit jamais achevée.]=],
		},
		{
			title = "La nouvelle frontière",
			hint = "Répondez à l'appel à l'aide du Cercle cénarien.",
			text = [=[Quand {link:moonglade}Reflet-de-Lune{/link} appela à l'aide dans le lointain ouest, Fandral confia l'affaire à {link:mathrengyl-bearwalker}Mathrengyl{/link} de mauvaise grâce, et donna un avertissement de son cru : ne pas être assez fou pour croire les paroles de Reflet-de-Lune.]=],
		},
	},
	mentions = {
		{ text = "La couronne de la terre" },
		{ text = "{link:teldrassil}Teldrassil{/link}" },
		{ text = "Le {link:grove-of-the-ancients}Bosquet des Anciens{/link}" },
		{ text = "La nouvelle frontière" },
		{ text = "Terre d'{link:un-goro-crater}Un'Goro{/link}" },
		{ text = "Recherches sur le grain-du-matin" },
		{ text = "Sélénien d'Élune" },
		{ text = "La couronne de la terre, la fiole qu'il écarta" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "dirige les druides à sa place" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "gouverne la cité qu'il éleva" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "son second" },
		{ id = "corithras-moonrage", name = "Corithras Moonrage", note = "lui envoie l'eau des puits de lune" },
	},
})

Translate("frFR", "rellian-greenspyre", {
	title = "Rellian Greenspyre",
	subtitle = "Druide de l'Enclave cénarienne",
	found = "Les sentiers de l'Enclave cénarienne",
	hint = [=[Trouvez le druide qui parcourt les sentiers de l'Enclave cénarienne.]=],
	allegiance = "Cercle cénarien",
	aliases = { "Rellian" },
	sections = {
		{
			title = "Résumé",
			text = [=[Rellian Greenspyre est un druide de {link:darnassus}Darnassus{/link} et un ami de {link:denalan}Denalan{/link} du {link:lake-al-ameth}Lac Al'Ameth{/link}. Il espérait faire pousser un sylvain à partir d'une graine pour aider les travaux de son ami, mais il découvrit que la corruption passe du parent à la graine. Tant qu'on n'aura pas trouvé de remède, dit-il, les sylvains les plus souillés doivent être abattus et leurs tumeurs brûlées.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudie la corruption des sylvains.
• Il brûle les tumeurs prélevées sur les sylvains du {link:wellspring-lake}Lac d'Aigue-vive{/link}.]=],
		},
	},
	mentions = {
		{ text = "Rellian Greenspyre" },
		{ text = "Tumeurs" },
		{ text = "Retour auprès de {link:denalan}Denalan{/link}" },
	},
	bonds = {
		{ id = "denalan", name = "Denalan", note = "son ami" },
	},
})

Translate("frFR", "mathrengyl-bearwalker", {
	title = "Mathrengyl Bearwalker",
	subtitle = "Second de l'archidruide",
	found = "Le deuxième étage de l'arbre de l'archidruide",
	hint = [=[Cherchez le second de l'archidruide à l'étage en dessous du sien.]=],
	allegiance = "Cercle cénarien",
	aliases = { "Mathrengyl" },
	sections = {
		{
			title = "Résumé",
			text = [=[Mathrengyl Bearwalker est l'assistant direct de l'archidruide, l'un des plus sages druides de {link:teldrassil}Teldrassil{/link}. Il forme les jeunes druides et les envoie à {link:moonglade}Reflet-de-Lune{/link}, quelles que soient les querelles de leurs aînés. Il parle franchement de ces querelles. La méfiance entre {link:darnassus}Darnassus{/link} et Reflet-de-Lune est réelle, admet-il, mais le devoir envers le Cercle demeure.]=],
		},
		{
			title = "Hauts faits",
