	allegiance = "Sentinelles",
	aliases = { "Thyn'tel" },
	sections = {
		{
			title = "Résumé",
			text = [=[Thyn'tel Bladeweaver est l'une des commandantes des {link:sentinels}Sentinelles{/link}. Elle garde les biens de la prêtresse Velinde Starsong, qui disparut de son poste en {link:ashenvale}Orneval{/link}. Les Sentinelles croyaient que Velinde avait ses propres raisons de partir. Ce que l'on apprit enfin dans les mines du {link:duskwood}Bois de la Pénombre{/link} prouva le contraire.]=],
