	},
})

Translate("frFR", "sentinels", {
	title = "Sentinelles",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Sentinelles sont les guerrières des {link:night-elves}elfes de la nuit{/link}. Depuis des milliers d'années, elles gardent les forêts de {link:kalimdor}Kalimdor{/link}, et elles répondent à la grande prêtresse d'Élune. La plupart sont des femmes, des chasseresses qui manient les dons de la déesse aussi bien que le glaive et l'arc.]=],
		},
		{
			title = "Origines",
			text = [=[Après la {link:great-sundering}Fracture{/link}, tandis que les druides dormaient dans le {link:emerald-dream}Rêve d'émeraude{/link}, les prêtresses d'Élune et leurs guerrières veillèrent sur les {link:night-elves}kaldorei{/link}. Au fil de ces longs âges, les Sentinelles devinrent le bouclier de leur peuple.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Des Sentinelles montent la garde dans chaque village de {link:teldrassil}Teldrassil{/link} et sur chaque route. Elles gardent l'arbre de l'Oracle, portent ses messages à {link:darnassus}Darnassus{/link}, et combattent les {link:gnarlpine-furbolgs}Pins-tordus{/link} et les harpies. Au-delà de l'arbre, elles tiennent des postes à {link:darkshore}Sombrivage{/link}, en {link:ashenvale}Orneval{/link} et à {link:feralas}Féralas{/link}. La {link:shandris-feathermoon}générale Feathermoon{/link} veille à ce que chacune ait le temps de prier, et à Darnassus elles surveillent la cité elle-même, car elles craignent que quelque chose n'aille pas.]=],
		},
	},
})
